import{_ as t,o as n,c as r,a2 as i}from"./chunks/framework.Buc7gXeZ.js";const g=JSON.parse('{"title":"Leerzustand anpassen","description":"Den Text ändern, der erscheint, wenn eine Ansicht keine Einträge zeigt.","frontmatter":{"title":"Leerzustand anpassen","description":"Den Text ändern, der erscheint, wenn eine Ansicht keine Einträge zeigt."},"headers":[],"relativePath":"ansichten/leerzustand.md","filePath":"ansichten/leerzustand.md","lastUpdated":1786089999000}'),a={name:"ansichten/leerzustand.md"};function s(d,e,l,h,o,c){return n(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="leerzustand-anpassen" tabindex="-1">Leerzustand anpassen <a class="header-anchor" href="#leerzustand-anpassen" aria-label="Permalink to &quot;Leerzustand anpassen&quot;">​</a></h1><p>Zeigt eine Ansicht keine Einträge, erscheint ein Hinweistext. Voreingestellt lautet er:</p><blockquote><p><strong>Keine Ergebnisse gefunden</strong><em>Passen Sie die Filter an oder erstellen Sie einen neuen Eintrag.</em></p></blockquote><p>Beides lässt sich ändern.</p><h2 id="andern" tabindex="-1">Ändern <a class="header-anchor" href="#andern" aria-label="Permalink to &quot;Ändern&quot;">​</a></h2><p>Über <strong>Weitere</strong> (⋮) → <strong>Leere Ansicht bearbeiten</strong>. Sie bearbeiten:</p><table tabindex="0"><thead><tr><th>Feld</th><th>Wirkung</th></tr></thead><tbody><tr><td><strong>Titel</strong></td><td>Die Überschrift</td></tr><tr><td><strong>Untertitel</strong></td><td>Der erklärende Text darunter</td></tr></tbody></table><p>Die Einstellung gilt <strong>je Ansicht</strong> — andere Ansichten desselben Grids bleiben unberührt.</p><h2 id="wann-sich-das-lohnt" tabindex="-1">Wann sich das lohnt <a class="header-anchor" href="#wann-sich-das-lohnt" aria-label="Permalink to &quot;Wann sich das lohnt&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Besonders in Portalen</p><p>„Keine Ergebnisse gefunden&quot; ist für Sie verständlich. Für einen Kunden, der ein <a href="/docs/seiten/portal-veroeffentlichen">Portal</a> öffnet, wirkt es wie ein Fehler.</p><p>Besser: „Für diesen Zeitraum liegen noch keine Buchungen vor.&quot; oder „Ihre Anfragen erscheinen hier, sobald sie bearbeitet wurden.&quot;</p></div><p>Weitere Fälle:</p><table tabindex="0"><thead><tr><th>Situation</th><th>Möglicher Text</th></tr></thead><tbody><tr><td>Aufgabenansicht, alles erledigt</td><td><em>Alles erledigt — nichts zu tun.</em></td></tr><tr><td>Gefilterte Ansicht „Überfällig&quot;</td><td><em>Keine überfälligen Vorgänge.</em></td></tr><tr><td>Neues Grid im Aufbau</td><td><em>Noch keine Daten. Legen Sie den ersten Eintrag an.</em></td></tr><tr><td>Portal für Kunden</td><td><em>Sobald Unterlagen vorliegen, erscheinen sie hier.</em></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Ein leerer Zustand kann eine gute Nachricht sein</p><p>Bei gefilterten Ansichten bedeutet „keine Einträge&quot; oft, dass nichts zu tun ist. Formulieren Sie den Text entsprechend — das ist informativer als eine neutrale Fehlanzeige.</p></div><h2 id="leer-heißt-nicht-immer-leer" tabindex="-1">Leer heißt nicht immer leer <a class="header-anchor" href="#leer-heißt-nicht-immer-leer" aria-label="Permalink to &quot;Leer heißt nicht immer leer&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Prüfen Sie die Ursache</p><p>Ein leerer Zustand kann mehrere Gründe haben:</p><table tabindex="0"><thead><tr><th>Ursache</th><th>Erkennbar an</th></tr></thead><tbody><tr><td>Das Grid ist tatsächlich leer</td><td>Auch ungefilterte Ansichten sind leer</td></tr><tr><td>Ein <strong>Filter</strong> blendet alles aus</td><td>Die Filter-Schaltfläche zeigt aktive Bedingungen</td></tr><tr><td>Ein <strong>temporärer Filter</strong> ist aktiv</td><td>Nur bei Ihnen, verschwindet nach der Sitzung</td></tr><tr><td>Eine <strong>Suche</strong> grenzt ein</td><td>Suchfeld ist gefüllt</td></tr></tbody></table><p>Bevor Sie den Text anpassen, vergewissern Sie sich, dass die Ansicht das Richtige zeigt.</p></div><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/docs/ansichten/was-ist-eine-ansicht">Was ist eine Ansicht</a></li><li><a href="/docs/ansichten/filtern-sortieren-gruppieren">Filtern, Sortieren, Gruppieren</a></li><li><a href="/docs/seiten/portal-veroeffentlichen">Portal veröffentlichen</a></li></ul>',17)])])}const b=t(a,[["render",s]]);export{g as __pageData,b as default};
